/**
 * Stylesheet imports resolve to the raw CSS text, not to a side effect:
 * esbuild inlines them with `--loader:.css=text`, Vite resolves `?inline` to the
 * stylesheet text, and Vitest returns the content through `test.css: true`.
 */

declare module '*.css?inline' {
  const css: string;
  export default css;
}

declare module '*.css' {
  const css: string;
  export default css;
}

/* Hooks: --an-select-height | --an-select-bg | --an-select-fg
   | --an-select-border-color | --an-select-radius | --an-select-font-size
   | --an-select-padding-x | --an-select-focus-ring | --an-select-panel-bg
   | --an-select-panel-max-height | --an-select-min-width.
   Colours and scales come from @an-ui-kit/tokens, each with a literal fallback. */

:host {
  display: inline-block;
  vertical-align: middle;
  box-sizing: border-box;
  border: 0 solid;
  margin: 0;
  line-height: 1.5;
  color-scheme: light dark;
  font-family: inherit;
  font-size: var(--an-select-font-size, var(--an-font-size-sm, 0.875rem));
  --an-select-bg: var(--an-color-bg-1, #ffffff);
  --an-select-fg: var(--an-color-fg-1, #18181b);
  --an-select-border-color: var(--an-color-border-1, #d4d4d8);
  --an-select-panel-bg: var(--an-color-bg-1, #ffffff);
}

:host([data-theme='dark']) {
  color-scheme: dark;
  --an-select-bg: var(--an-color-bg-1, #18181b);
  --an-select-fg: var(--an-color-fg-1, #f4f4f5);
  --an-select-border-color: var(--an-color-border-1, #3f3f46);
  --an-select-panel-bg: var(--an-color-bg-2, #27272a);
}

:host([data-theme='light']) {
  color-scheme: light;
  --an-select-bg: var(--an-color-bg-1, #ffffff);
  --an-select-fg: var(--an-color-fg-1, #18181b);
  --an-select-border-color: var(--an-color-border-1, #d4d4d8);
  --an-select-panel-bg: var(--an-color-bg-1, #ffffff);
}

@media (prefers-color-scheme: dark) {
  :host(:not([data-theme='light'])) {
    color-scheme: dark;
    --an-select-bg: var(--an-color-bg-1, #18181b);
    --an-select-fg: var(--an-color-fg-1, #f4f4f5);
    --an-select-border-color: var(--an-color-border-1, #3f3f46);
    --an-select-panel-bg: var(--an-color-bg-2, #27272a);
  }
}

/* The light-DOM option list is data; it must never paint a second time. */
::slotted(option) {
  display: none !important;
}

[hidden] {
  display: none !important;
}

.base {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  min-width: var(--an-select-min-width, 12rem);
  font-family: inherit;
}

.label {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  color: var(--an-select-fg, var(--an-color-fg-1, #18181b));
  font-size: var(--an-font-size-sm, 0.875rem);
  line-height: 1.4;
}

.control {
  position: relative;
  display: block;
  width: 100%;
}

.trigger {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 0.375rem;
  width: 100%;
  min-width: 0;
  height: var(--an-select-height, var(--an-space-9, 2.25rem));
  padding: 0 calc(var(--an-select-padding-x, var(--an-space-3, 0.75rem)) + 1.25rem) 0
    var(--an-select-padding-x, var(--an-space-3, 0.75rem));
  border: 1px solid var(--an-select-border-color, var(--an-color-border-1, #d4d4d8));
  border-radius: var(--an-select-radius, var(--an-radius-md, 0.5rem));
  background: var(--an-select-bg, var(--an-color-bg-1, #ffffff));
  color: var(--an-select-fg, var(--an-color-fg-1, #18181b));
  font-family: inherit;
  font-size: inherit;
  line-height: 1.4;
  text-align: left;
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
  user-select: none;
  overflow: hidden;
}

.trigger:focus-visible {
  outline: 2px solid var(--an-select-focus-ring, var(--an-color-accent-9, #2563eb));
  outline-offset: 1px;
  border-color: var(--an-select-focus-ring, var(--an-color-accent-9, #2563eb));
}

.trigger[aria-disabled='true'] {
  cursor: not-allowed;
  opacity: 0.55;
}

.trigger[aria-invalid='true'] {
  border-color: var(--an-color-danger-9, #dc2626);
}

.value,
.placeholder {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.placeholder {
  color: var(
    --an-color-fg-3,
    color-mix(in srgb, var(--an-select-fg, #626262) 68%, var(--an-select-bg, #626262))
  );
}

/* Self-drawn arrow: a border triangle, so no image asset is needed. */
.chevron {
  position: absolute;
  top: 50%;
  right: var(--an-select-padding-x, var(--an-space-3, 0.75rem));
  width: 0;
  height: 0;
  margin-top: -0.175rem;
  border-left: 0.3rem solid transparent;
  border-right: 0.3rem solid transparent;
  border-top: 0.35rem solid var(--an-select-fg, var(--an-color-fg-1, #18181b));
  opacity: 0.6;
  pointer-events: none;
}

.trigger.is-open .chevron {
  transform: rotate(180deg);
}

.tags {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: 0.25rem;
  min-width: 0;
  overflow: hidden;
}

.tag {
  display: inline-flex;
  flex: 0 1 auto;
  align-items: center;
  gap: 0.125rem;
  max-width: 9rem;
  padding: 0.0625rem 0.25rem 0.0625rem 0.375rem;
  border-radius: var(--an-radius-sm, 0.375rem);
  background: var(--an-color-bg-2, #f4f4f5);
  color: var(--an-select-fg, var(--an-color-fg-1, #18181b));
  font-size: var(--an-font-size-xs, 0.8125rem);
  line-height: 1.4;
}

.tag-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tag-remove {
  padding: 0 0.125rem;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  line-height: 1;
  cursor: pointer;
  opacity: 0.7;
}

.tag-remove:hover {
  opacity: 1;
}

.tag-overflow {
  flex: 0 0 auto;
  color: var(--an-color-fg-3, #a1a1aa);
  font-size: var(--an-font-size-xs, 0.8125rem);
  white-space: nowrap;
}

.panel {
  box-sizing: border-box;
  min-width: 100%;
  overflow: hidden;
  border: 1px solid var(--an-select-border-color, var(--an-color-border-1, #d4d4d8));
  border-radius: var(--an-select-radius, var(--an-radius-md, 0.5rem));
  background: var(--an-select-panel-bg, var(--an-color-bg-1, #ffffff));
  color: var(--an-select-fg, var(--an-color-fg-1, #18181b));
  box-shadow: 0 10px 15px -3px rgb(0 0 0 / 10%), 0 4px 6px -4px rgb(0 0 0 / 10%);
  font-size: inherit;
}

.search-wrap {
  display: flex;
  align-items: center;
  padding: 0.375rem;
  border-bottom: 1px solid var(--an-select-border-color, var(--an-color-border-1, #d4d4d8));
}

.search {
  box-sizing: border-box;
  width: 100%;
  height: var(--an-space-8, 2rem);
  padding: 0 0.5rem;
  border: 1px solid var(--an-select-border-color, var(--an-color-border-1, #d4d4d8));
  border-radius: var(--an-radius-sm, 0.375rem);
  background: var(--an-select-bg, var(--an-color-bg-1, #ffffff));
  color: inherit;
  font: inherit;
  outline: none;
}

.search:focus-visible {
  border-color: var(--an-select-focus-ring, var(--an-color-accent-9, #2563eb));
}

.listbox {
  max-height: var(--an-select-panel-max-height, 20rem);
  overflow-y: auto;
  padding: 0.25rem;
  overscroll-behavior: contain;
}

.option {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  height: 2.5rem;
  padding: 0 0.5rem;
  border-radius: var(--an-radius-sm, 0.375rem);
  cursor: pointer;
}

/* One `<an-option-group>`; the wrapper is flattened into the virtual rows, so it
   must not add vertical space — only the options inside it are 40px rows. */
.group {
  display: flex;
  flex-direction: column;
}

.group[data-disabled='true'] {
  cursor: not-allowed;
}

.option[data-active='true'] {
  background: var(--an-color-bg-2, #f4f4f5);
}

.option[aria-selected='true'] {
  color: var(--an-color-accent-9, #2563eb);
}

.option[aria-disabled='true'] {
  cursor: not-allowed;
  opacity: 0.5;
}

.option-content {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  gap: 0.375rem;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.option-indicator {
  flex: 0 0 auto;
  width: 1rem;
  text-align: center;
  visibility: hidden;
}

.option[aria-selected='true'] .option-indicator {
  visibility: visible;
}

.virtual-spacer {
  position: relative;
}

.virtual-window,
.virtual-active {
  position: absolute;
  left: 0;
  right: 0;
}

.empty,
.loading {
  padding: 0.75rem;
  color: var(--an-color-fg-3, #a1a1aa);
  text-align: center;
}

.loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
}

.spinner {
  width: 0.875rem;
  height: 0.875rem;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: an-select-spin 0.7s linear infinite;
}

@keyframes an-select-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .spinner {
    animation: none;
  }
}

:host([size='sm']) .trigger {
  height: var(--an-select-height, var(--an-space-8, 2rem));
  padding: 0 calc(var(--an-select-padding-x, var(--an-space-2, 0.5rem)) + 1rem) 0
    var(--an-select-padding-x, var(--an-space-2, 0.5rem));
  border-radius: var(--an-select-radius, var(--an-radius-sm, 0.375rem));
  font-size: var(--an-select-font-size, var(--an-font-size-xs, 0.8125rem));
}

:host([size='sm']) .chevron {
  right: var(--an-select-padding-x, var(--an-space-2, 0.5rem));
}

:host([size='lg']) .trigger {
  height: var(--an-select-height, var(--an-space-11, 2.75rem));
  padding: 0 calc(var(--an-select-padding-x, var(--an-space-4, 1rem)) + 1.25rem) 0
    var(--an-select-padding-x, var(--an-space-4, 1rem));
  border-radius: var(--an-select-radius, var(--an-radius-lg, 0.625rem));
  font-size: var(--an-select-font-size, var(--an-font-size-md, 1rem));
}

:host([size='lg']) .chevron {
  right: var(--an-select-padding-x, var(--an-space-4, 1rem));
}

/* Guards against page-level preflight (e.g. Tailwind v4) leaking into the host. */
:host {
  box-sizing: border-box;
  border: 0 solid;
  margin: 0;
  line-height: 1.5;
}

import resetStyles from './reset.css?inline';

/** Values allowed for attribute-backed properties. */
export type Primitive = string | number | boolean;

/** Defaults for attribute-backed properties; keys define the public API. */
export type Defaults = Record<string, Primitive>;

/** Defaults for list properties; an attribute holds the items comma-separated. */
export type ArrayDefaults = Record<string, string[]>;

/** `my-attr` -> `myAttr`, so an attribute can drive the camelCase property. */
function toCamelCase(name: string): string {
  return name.replace(/-([a-z0-9])/g, (_, char: string) => char.toUpperCase());
}

/** `myAttr` -> `my-attr`, so a property can reflect to the attribute. */
function toKebabCase(name: string): string {
  return name.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
}

/** `"a, b"` -> `['a', 'b']`; an absent attribute restores the fallback list. */
function toList(value: string | null, fallback: readonly string[]): string[] {
  if (value === null) return [...fallback];
  return value
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

/** Order-sensitive comparison, used to skip redundant writes and renders. */
function sameList(a: readonly string[], b: readonly string[]): boolean {
  return a.length === b.length && a.every((part, index) => part === b[index]);
}

/**
 * Dependency-free base class for every `an-*` custom element.
 *
 * Contract:
 * - Constructor only touches `this` (`attachShadow`, `attachInternals`, local
 *   fields, accessors): it never reads `document`, `window`, storage or the
 *   network, so importing a component stays safe under SSR and inside workers.
 * - `static defaults` declares the attribute-backed API. Property accessors are
 *   generated from it and reflect back to attributes, so `el.variant` and
 *   `variant="primary"` can never disagree; attributes stay the source of truth.
 * - Markup comes from `render()` as an HTML string and is written straight into
 *   the shadow root, including `static styles` plus the shared reset.
 * - Listeners belong on the shadow root (event delegation), because re-rendering
 *   replaces the inner markup.
 * - Every write re-renders before it returns, so `el.disabled = true` followed by
 *   a synchronous `shadowRoot` read already sees the new markup.
 * - Form participation is opt-in: a subclass sets `static formAssociated = true`
 *   and then gets `this.internals`, the platform lifecycle callbacks
 *   (`formAssociatedCallback`, `formResetCallback`, `formDisabledCallback`) and
 *   the protected `onFormReset` / `onFormDisabled` hooks.
 * - `static arrayDefaults` opts an attribute into a comma-separated `string[]`
 *   property. Elements that do not declare it keep a scalar-only API.
 * - `checkValidity()` / `reportValidity()` / `reset()` / `getFormData()` wrap the
 *   platform form surface so a subclass does not repeat it.
 */
export abstract class AnElement extends HTMLElement {
  /** Shadow-DOM stylesheet source for this element. */
  static styles: string = '';

  /** Attribute-backed properties and their defaults. */
  static defaults: Defaults = {};

  /**
   * Array-backed properties and their defaults. The attribute holds the items
   * comma-separated (`items="a, b"`); the property is a `string[]`.
   */
  static arrayDefaults: ArrayDefaults = {};

  /** Attributes the browser reports to `attributeChangedCallback`. */
  static get observedAttributes(): string[] {
    return [
      ...Object.keys(this.defaults).map(toKebabCase),
      ...Object.keys(this.arrayDefaults).map(toKebabCase),
    ];
  }

  /**
   * Opts the element into `ElementInternals` form participation.
   * Subclasses that submit/reset/validate through a form set this to `true`.
   */
  static formAssociated: boolean = false;

  /**
   * Platform form internals, attached only when `static formAssociated` is
   * `true`. `null` on elements that did not opt in and on DOM implementations
   * without `attachInternals()`.
   */
  protected internals: ElementInternals | null = null;

  #defaults: Defaults = {};
  #values: Record<string, Primitive> = {};
  #arrayDefaults: ArrayDefaults = {};
  #arrays: Record<string, string[]> = {};
  #rendered = false;
  #reflecting = false;
  #fallbackStyle: HTMLStyleElement | null = null;

  constructor() {
    super();
    const ctor = this.constructor as typeof AnElement;
    const root = this.attachShadow({ mode: 'open' });

    if (ctor.formAssociated) {
      try {
        this.internals = this.attachInternals();
      } catch {
        // `attachInternals()` throws unless the element opted in, and some DOM
        // implementations (e.g. happy-dom) do not expose it at all: degrade to a
        // plain element instead of failing construction.
        this.internals = null;
      }
    }

    this.#defaults = ctor.defaults;
    this.#values = { ...ctor.defaults };
    this.#arrayDefaults = ctor.arrayDefaults;
    this.#arrays = {};
    for (const key of Object.keys(ctor.arrayDefaults)) {
      this.#arrays[key] = [...ctor.arrayDefaults[key]];
    }
    this.#adoptStyles(root, `${resetStyles}\n${ctor.styles}`);

    for (const [key, fallback] of Object.entries(ctor.defaults)) {
      const type = typeof fallback;
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => this.#values[key],
        set: (next: Primitive) => this.#assign(key, next, type),
      });
    }

    for (const key of Object.keys(ctor.arrayDefaults)) {
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => [...(this.#arrays[key] ?? [])],
        set: (next: string[] | string) => this.#assignList(key, next),
      });
    }
  }

  connectedCallback(): void {
    if (!this.#rendered) {
      this.#rendered = true;
      this.requestUpdate();
    }
    this.onConnect();
  }

  /** Re-renders the shadow root from `render()`. */
  requestUpdate(): void {
    const root = this.shadowRoot;
    if (!root || !this.#rendered) return;
    root.innerHTML = this.render();
    if (this.#fallbackStyle && !this.#fallbackStyle.isConnected) root.prepend(this.#fallbackStyle);
    this.afterRender();
  }

  disconnectedCallback(): void {
    this.onDisconnect();
  }

  /**
   * Platform callback: the element was associated with, or disassociated from,
   * a form. Association itself is opt-in, so the default implementation is a
   * no-op; a subclass may read `this.internals?.form` here.
   */
  formAssociatedCallback(): void {}

  /** Platform callback: the owning form was reset. */
  formResetCallback(): void {
    this.onFormReset();
  }

  /** Platform callback: the platform disabled or enabled the element. */
  formDisabledCallback(disabled: boolean): void {
    this.onFormDisabled(disabled);
  }

  /**
   * Constraint validation in the owning form. Forwards to `ElementInternals`
   * when available; without internals there is nothing to validate, so it
   * reports `true`.
   */
  checkValidity(): boolean {
    const internals = this.internals;
    if (!internals || typeof internals.checkValidity !== 'function') return true;
    return internals.checkValidity();
  }

  /** Like `checkValidity()`, but asks the platform to report the problem. */
  reportValidity(): boolean {
    const internals = this.internals;
    if (!internals || typeof internals.reportValidity !== 'function') return true;
    return internals.reportValidity();
  }

  /**
   * Resets the control to the state it was mounted with and re-renders.
   * Delegates to `formResetCallback()` so a subclass only overrides
   * `onFormReset()`.
   */
  reset(): void {
    this.formResetCallback();
    this.requestUpdate();
  }

  /**
   * Serializes this element the way `new FormData(form)` would: one row per
   * `formEntries()` entry, or `null` when the element submits nothing.
   */
  getFormData(): FormData | null {
    const entries = this.formEntries();
    if (entries.length === 0) return null;
    const data = new FormData();
    for (const [name, value] of entries) data.append(name, value);
    return data;
  }

  /**
   * Rows this element contributes to `FormData`. Defaults to `name` + `value`
   * when both are usable; subclasses with a richer payload override it.
   */
  protected formEntries(): Array<[string, string | File]> {
    const { name, value } = this as unknown as { name?: unknown; value?: unknown };
    if (typeof name !== 'string' || name.length === 0) return [];
    if (typeof value !== 'string' && typeof value !== 'number') return [];
    return [[name, String(value)]];
  }

  /** Hook: connected and rendered; default no-op. */
  protected onConnect(): void {}

  /** Hook: disconnected from the document; default no-op. */
  protected onDisconnect(): void {}

  /** Hook: the owning form was reset; restore state here. Default no-op. */
  protected onFormReset(): void {}

  /** Hook: the platform-level disabled state changed; default no-op. */
  protected onFormDisabled(disabled: boolean): void {}

  /** Returns the shadow-DOM markup; called on connect and after every change. */
  protected abstract render(): string;

  /** Hook for state markup cannot express (e.g. `.disabled` on a child node). */
  protected afterRender(): void {}

  /** Dispatches a bubbling, composed `CustomEvent`. */
  emit<T>(name: string, detail?: T): boolean {
    return this.dispatchEvent(new CustomEvent<T>(name, { bubbles: true, composed: true, detail }));
  }

  attributeChangedCallback(name: string, oldValue: string | null, value: string | null): void {
    if (oldValue === value) return;
    const key = toCamelCase(name);
    if (key in this.#arrayDefaults) {
      this.#arrays[key] = toList(value, this.#arrayDefaults[key]); // attribute -> list property
      if (this.#rendered && !this.#reflecting) this.requestUpdate();
      return;
    }
    if (!(key in this.#defaults)) return;
    this.#values[key] = this.#coerce(key, value); // attribute -> camelCase property
    if (this.#rendered && !this.#reflecting) this.requestUpdate();
  }

  #assignList(key: string, next: string[] | string): void {
    const value = Array.isArray(next)
      ? next.map((part) => String(part).trim()).filter((part) => part.length > 0)
      : toList(next, []);
    if (sameList(this.#arrays[key] ?? [], value)) return;
    this.#arrays[key] = value;
    this.#reflectList(key, value);
  }

  #reflectList(key: string, value: string[]): void {
    const attribute = toKebabCase(key);
    const fallback = this.#arrayDefaults[key] ?? [];
    this.#reflecting = true;
    try {
      if (value.length === 0 || sameList(value, fallback)) this.removeAttribute(attribute);
      else this.setAttribute(attribute, value.join(','));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #assign(key: string, next: Primitive, type: string): void {
    const value = type === 'boolean' ? Boolean(next) : type === 'number' ? Number(next) : String(next);
    if (Object.is(this.#values[key], value)) return;
    this.#values[key] = value;
    this.#reflect(key, value);
  }

  #reflect(key: string, value: Primitive): void {
    const attribute = toKebabCase(key);
    this.#reflecting = true;
    try {
      if (typeof value === 'boolean') this.toggleAttribute(attribute, value);
      else if (value === this.#defaults[key]) this.removeAttribute(attribute);
      else this.setAttribute(attribute, String(value));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #coerce(key: string, value: string | null): Primitive {
    const fallback = this.#defaults[key];
    if (typeof fallback === 'boolean') return value !== null;
    if (value === null) return fallback;
    if (typeof fallback === 'number') return Number.isNaN(Number(value)) ? fallback : Number(value);
    return value;
  }

  #adoptStyles(root: ShadowRoot, text: string): void {
    if (!text.trim()) return;
    try {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(text);
      root.adoptedStyleSheets = [sheet];
    } catch {
      if (typeof document === 'undefined') return;
      const style = document.createElement('style');
      style.textContent = text;
      root.prepend(style);
      this.#fallbackStyle = style;
    }
  }
}

/**
 * Anchored floating panel used by the overlay components (select, date picker,
 * combobox). Framework-free and dependency-free.
 *
 * The panel is promoted to the top layer through `popover="manual"` +
 * `showPopover()` when the platform supports it, and falls back to plain
 * `position: fixed` when it does not. Position is computed from
 * `getBoundingClientRect()` (viewport coordinates) with a vertical flip when the
 * space below the anchor is too small and a horizontal shift that keeps the
 * panel inside the viewport.
 */

/** Viewport margin that the horizontal shift keeps free on both sides. */
const VIEWPORT_MARGIN = 8;

/** Options accepted by `AnPopover`. */
export interface AnPopoverOptions {
  /** Element the panel is anchored to. */
  anchor: HTMLElement;
  /** Panel element that gets shown next to the anchor. */
  floating: HTMLElement;
  /** Keep the panel at least as wide as the anchor. Default: `true`. */
  matchWidth?: boolean;
  /** Gap between anchor and panel, in pixels. Default: `4`. */
  offset?: number;
  /** Called after a dismissal (outside pointerdown / Escape) closed the panel. */
  onClose?: () => void;
}

/** Inline styles `AnPopover` writes, so `close()` can put them back. */
interface SavedStyles {
  position: string;
  top: string;
  left: string;
  minWidth: string;
  inset: string;
  margin: string;
}

/**
 * Positions and dismisses one floating panel.
 *
 * `open()` / `close()` are idempotent; `close()` fires `onClose` only when the
 * panel actually was open, so a programmatic close and a dismissal notify the
 * owner the same way. `destroy()` tears the listeners and the popover state down
 * without notifying.
 */
export class AnPopover {
  #anchor: HTMLElement;
  #floating: HTMLElement;
  #matchWidth: boolean;
  #offset: number;
  #onClose?: () => void;
  #isOpen = false;
  /** Whether the panel currently sits in the top layer via the popover API. */
  #topLayer = false;
  /** `popover` attribute value found before `open()`, restored by `close()`. */
  #savedPopover: string | null = null;
  #savedStyles: SavedStyles | null = null;

  constructor(options: AnPopoverOptions) {
    this.#anchor = options.anchor;
    this.#floating = options.floating;
    this.#matchWidth = options.matchWidth ?? true;
    this.#offset = options.offset ?? 4;
    this.#onClose = options.onClose;
  }

  /** Whether the panel is currently shown. */
  get isOpen(): boolean {
    return this.#isOpen;
  }

  /** Shows the panel, positions it and starts tracking the viewport. */
  open(): void {
    if (this.#isOpen) return;
    this.#isOpen = true;
    this.#enterTopLayer();
    this.#captureStyles();
    this.reposition();
    this.#listen();
  }

  /** Hides the panel, stops tracking and notifies `onClose`. */
  close(): void {
    if (!this.#isOpen) return;
    this.#isOpen = false;
    this.#unlisten();
    this.#leaveTopLayer();
    this.#restoreStyles();
    this.#onClose?.();
  }

  /** Closes the panel when open, opens it otherwise. */
  toggle(): void {
    if (this.#isOpen) this.close();
    else this.open();
  }

  /** Recomputes the panel position from the current anchor rect. No-op closed. */
  reposition(): void {
    if (!this.#isOpen) return;
    const anchor = this.#anchor.getBoundingClientRect();
    const floating = this.#floating.getBoundingClientRect();
    const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 0;
    const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
    const gap = this.#offset;
    const width = this.#matchWidth ? anchor.width : floating.width;
    const height = floating.height;

    // Below the anchor by default; flip above when it does not fit and there is
    // more room on the other side.
    let top = anchor.bottom + gap;
    const below = viewportHeight - anchor.bottom - gap;
    const above = anchor.top - gap;
    if (height > below && above > below) top = anchor.top - gap - height;

    // Keep both edges inside the viewport; a panel wider than the viewport
    // sticks to the left margin instead of going negative.
    const maxLeft = viewportWidth - VIEWPORT_MARGIN - width;
    const left = Math.min(
      Math.max(anchor.left, VIEWPORT_MARGIN),
      Math.max(maxLeft, VIEWPORT_MARGIN),
    );

    const style = this.#floating.style;
    style.top = `${Math.round(top)}px`;
    style.left = `${Math.round(left)}px`;
    if (this.#matchWidth) style.minWidth = `${Math.round(anchor.width)}px`;
  }

  /** Removes every listener, hides the panel and restores its inline styles. */
  destroy(): void {
    this.#isOpen = false;
    this.#unlisten();
    this.#leaveTopLayer();
    this.#restoreStyles();
  }

  /** Promotes the panel to the top layer when the popover API exists. */
  #enterTopLayer(): void {
    const floating = this.#floating;
    if (typeof floating.showPopover !== 'function') return;
    const previous = floating.getAttribute('popover');
    try {
      floating.setAttribute('popover', 'manual');
      floating.showPopover();
      this.#savedPopover = previous;
      this.#topLayer = true;
    } catch {
      // An implementation may expose the method but refuse to show (e.g. the
      // element is not connected): keep the attribute state untouched.
      if (previous === null) floating.removeAttribute('popover');
      else floating.setAttribute('popover', previous);
    }
  }

  /** Leaves the top layer and restores the `popover` attribute. */
  #leaveTopLayer(): void {
    if (this.#topLayer) {
      try {
        this.#floating.hidePopover();
      } catch {
        // Already hidden by the platform (e.g. a forced close).
      }
      const previous = this.#savedPopover;
      if (previous === null) this.#floating.removeAttribute('popover');
      else this.#floating.setAttribute('popover', previous);
    }
    this.#topLayer = false;
    this.#savedPopover = null;
  }

  /** Records the inline styles this class overrides and applies the overrides. */
  #captureStyles(): void {
    const style = this.#floating.style;
    this.#savedStyles = {
      position: style.position,
      top: style.top,
      left: style.left,
      minWidth: style.minWidth,
      inset: style.inset,
      margin: style.margin,
    };
    style.position = 'fixed';
    style.inset = 'auto';
    style.margin = '0';
  }

  /** Restores the inline styles captured by `#captureStyles()`. */
  #restoreStyles(): void {
    const saved = this.#savedStyles;
    this.#savedStyles = null;
    if (!saved) return;
    const style = this.#floating.style;
    style.position = saved.position;
    style.top = saved.top;
    style.left = saved.left;
    style.minWidth = saved.minWidth;
    style.inset = saved.inset;
    style.margin = saved.margin;
  }

  #listen(): void {
    // `capture: true` also sees scrolls that happen in inner scroll containers.
    document.addEventListener('scroll', this.#onScroll, { capture: true, passive: true });
    window.addEventListener('resize', this.#onResize);
    document.addEventListener('pointerdown', this.#onPointerDown, true);
    document.addEventListener('keydown', this.#onKeyDown, true);
  }

  #unlisten(): void {
    document.removeEventListener('scroll', this.#onScroll, true);
    window.removeEventListener('resize', this.#onResize);
    document.removeEventListener('pointerdown', this.#onPointerDown, true);
    document.removeEventListener('keydown', this.#onKeyDown, true);
  }

  #onScroll = (): void => {
    this.reposition();
  };

  #onResize = (): void => {
    this.reposition();
  };

  /**
   * Closes on a pointerdown outside both the anchor and the panel. The composed
   * path is used first so a target inside a shadow tree still counts as inside.
   */
  #onPointerDown = (event: Event): void => {
    if (!this.#isOpen) return;
    const path = typeof event.composedPath === 'function' ? event.composedPath() : [];
    if (path.includes(this.#anchor) || path.includes(this.#floating)) return;
    if (path.length === 0) {
      const target = event.target;
      if (target instanceof Node && (this.#anchor.contains(target) || this.#floating.contains(target))) {
        return;
      }
    }
    this.close();
  };

  #onKeyDown = (event: KeyboardEvent): void => {
    if (event.key !== 'Escape') return;
    this.close();
  };
}

/* Options are read from the light DOM of <an-select>; the select draws the list. */
:host {
  display: none;
}

import optionStyles from './an-option.css?inline';
import { AnElement } from '../internal/base';

/**
 * `<an-option>` — one option of an `<an-select>`.
 *
 * The element renders nothing: `<an-select>` reads the `value` / `label` /
 * `disabled` state and the text content of its light-DOM `<an-option>` children,
 * then draws the list in its own shadow root. Because the host is `display:none`
 * the markup stays authorable without JavaScript and without being painted
 * twice.
 *
 * @attr {string} value - Value submitted when this option is selected. Default: the trimmed text content.
 * @attr {boolean} disabled - Prevents the option from being selected. Default: false.
 * @attr {string} label - Accessible name. Default: the trimmed text content.
 * @slot - Option label, used when `label` and `value` are absent.
 */
export class AnOption extends AnElement {
  static override styles: string = optionStyles;

  /** The owning `<an-select>` submits the chosen value, never the option. */
  static override formAssociated = false;

  static override defaults = { disabled: false };

  declare disabled: boolean;

  /** Selected value; an attribute wins, otherwise the trimmed text content. */
  get value(): string {
    const attribute = this.getAttribute('value');
    return attribute === null ? (this.textContent ?? '').trim() : attribute;
  }

  set value(next: string) {
    this.setAttribute('value', String(next));
  }

  /** Accessible name; an empty `label` falls back to the trimmed text content. */
  get label(): string {
    const attribute = this.getAttribute('label');
    return attribute === null || attribute.trim() === ''
      ? (this.textContent ?? '').trim()
      : attribute;
  }

  set label(next: string) {
    if (String(next).trim() === '') this.removeAttribute('label');
    else this.setAttribute('label', String(next));
  }

  /** Options are data for `<an-select>`; they never paint their own markup. */
  protected override render(): string {
    return '';
  }
}

import selectStyles from './an-select.css?inline';
import { AnElement } from '../internal/base';
import { AnPopover } from '../internal/popover';
import type { AnOption } from '../option/an-option';

/** Control sizes of `<an-select>`. */
export type AnSelectSize = 'sm' | 'md' | 'lg';
/** Rendering strategies of the option list. */
export type AnSelectVirtual = 'auto' | 'on' | 'off';

/** A public snapshot of one option. */
export interface AnSelectOption {
  /** Value submitted when this option is selected. */
  value: string;
  /** Visible / accessible text of the option. */
  label: string;
  /** Whether the option can be picked. */
  disabled: boolean;
}

/** A public snapshot of one `<an-option-group>`. */
export interface AnSelectGroup {
  /** Accessible name of the group, rendered as the wrapper's `aria-label`. */
  label: string;
  /** Whether the whole group is disabled. */
  disabled: boolean;
}

/** Payload of `an-load-more`. */
export interface AnSelectLoadMoreDetail {
  /** Current scroll offset of the listbox, in pixels. */
  scrollTop: number;
  /** Full scrollable height of the listbox, in pixels. */
  scrollHeight: number;
  /** Visible height of the listbox, in pixels. */
  clientHeight: number;
}

const SIZES: readonly AnSelectSize[] = ['sm', 'md', 'lg'];
const VIRTUAL_MODES: readonly AnSelectVirtual[] = ['auto', 'on', 'off'];

/** Shown to the owning form when `required` is set and nothing is selected. */
const REQUIRED_MESSAGE = '此字段为必填项。';

/** Fixed row height used by the virtual window, in pixels. */
const ITEM_HEIGHT = 40;
/** Extra rows rendered above and below the visible window when virtualizing. */
const VIRTUAL_BUFFER = 5;
/** Viewport height assumed when the listbox has not been laid out yet. */
const VIRTUAL_VIEWPORT = 320;
/** How long a search query must stay unchanged before `an-search` fires. */
const SEARCH_DEBOUNCE = 150;
/** How long single keystrokes accumulate into one typeahead query. */
const TYPEAHEAD_TIMEOUT = 500;
/** Minimum gap between two `an-load-more` events, in milliseconds. */
const LOAD_MORE_INTERVAL = 200;

/** Internal, richer view of one light-DOM option. */
interface OptionRecord extends AnSelectOption {
  /** Source light-DOM node; also used to keep option ids stable. */
  node: Element;
  /** Plain text used by the typeahead search. */
  text: string;
  /** Markup mirrored into the list item (author HTML or escaped text). */
  html: string;
  /** Stable element id referenced by `aria-activedescendant`. */
  id: string;
  /** Enclosing `<an-option-group>` metadata, `null` for a flat option. */
  group: AnSelectGroup | null;
  /** 1-based position inside `group`, recomputed after every filter pass. */
  posInGroup: number;
  /** Number of visible options inside `group`, recomputed after every filter pass. */
  groupSize: number;
}

let selectUid = 0;

function toCamelCase(name: string): string {
  return name.replace(/-([a-z0-9])/g, (_, char: string) => char.toUpperCase());
}

function oneOf<T extends string>(allowed: readonly T[], value: string, fallback: T): T {
  return (allowed as readonly string[]).includes(value) ? (value as T) : fallback;
}

const HTML_ESCAPES: Record<string, string> = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

/** Escapes text used inside an attribute value or element content. */
function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char: string) => HTML_ESCAPES[char] ?? char);
}

/** Parses a comma-separated `values` attribute. */
function parseValuesAttribute(value: string | null): string[] {
  if (value === null) return [];
  return value
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

/** Normalizes a selection list: no empty values, no duplicates, at most one in single mode. */
function normalizeValues(input: Iterable<string>, multiple: boolean): string[] {
  const seen = new Set<string>();
  const next: string[] = [];
  for (const raw of input) {
    const value = String(raw);
    if (value === '' || seen.has(value)) continue;
    seen.add(value);
    next.push(value);
    if (!multiple) break;
  }
  return next;
}

function sameList(left: readonly string[], right: readonly string[]): boolean {
  if (left.length !== right.length) return false;
  return left.every((value, index) => value === right[index]);
}

/** Whether a light-DOM child is an option source the select understands. */
function isOptionNode(node: Element): boolean {
  return node.localName === 'an-option' || node.localName === 'option';
}

/**
 * Reads the `<an-option-group>` metadata. One object is shared by every option
 * of the group, so a group can be used as a map key while rendering.
 */
function readGroup(node: Element): AnSelectGroup {
  const element = node as Element & { label?: unknown };
  const attribute = node.getAttribute('label');
  const label =
    typeof element.label === 'string' ? element.label : (attribute ?? '');
  return {
    label,
    disabled: node.hasAttribute('disabled') || (element as { disabled?: unknown }).disabled === true,
  };
}

/**
 * `<an-select>` — a self-drawn listbox with a light-DOM option source.
 *
 * The author writes `<an-option>` (or plain `<option>`) children; the element
 * reads them through a `MutationObserver` and mirrors them into its own
 * `role="listbox"` panel. Focus never enters the list: the trigger stays a
 * `role="combobox"` and points at the active row through
 * `aria-activedescendant`, so keyboard interaction survives shadow re-renders.
 *
 * @attr {string} label - Visible label above the trigger. Default: empty.
 * @attr {string} placeholder - Text shown while nothing is selected. Default: empty.
 * @attr {'sm'|'md'|'lg'} size - Control size. Default: `md`.
 * @attr {string} name - Form field name. Default: empty.
 * @attr {boolean} disabled - Blocks interaction and form submission. Default: false.
 * @attr {boolean} required - Marks the field as mandatory. Default: false.
 * @attr {boolean} invalid - Applies the invalid styling and `aria-invalid`. Default: false.
 * @attr {string} value - Initial/current single value. The property never writes back the attribute.
 * @attr {string} values - Multi-select values, comma separated.
 * @attr {boolean} multiple - Turns the control into a multi-select. Default: false.
 * @attr {boolean} searchable - Renders a local search box in the panel. Default: false.
 * @attr {boolean} loading - Shows the loading row. Default: false.
 * @attr {'auto'|'on'|'off'} virtual - Virtualization mode. Default: `auto`.
 * @attr {number} max-tags - Tags shown on a multi-select trigger before `+N`. Default: 3.
 * @attr {number} load-more-threshold - Distance from the list bottom, in pixels, at which `an-load-more` fires. Default: 80.
 * @attr {boolean} open - Whether the panel is open. Reflected by the property.
 *
 * @fires an-select-change - User changed the selection. Detail: `{ value, values, option, originalEvent }`.
 * @fires an-select-open - The panel opened.
 * @fires an-select-close - The panel closed.
 * @fires an-search - Debounced search query. Detail: `{ query }`.
 * @fires an-load-more - The list scrolled within `load-more-threshold` of the bottom; throttled to one event per 200ms. Detail: `{ scrollTop, scrollHeight, clientHeight }`.
 *
 * @slot - `<an-option>` / `<option>` children, or `<an-option-group>` wrappers holding them; they stay in the light DOM.
 *
 * @csspart base - Column wrapper around the label and the control.
 * @csspart label - Visible label.
 * @csspart trigger - The combobox trigger.
 * @csspart placeholder - Placeholder text slot.
 * @csspart tags - Tag container on a multi-select trigger.
 * @csspart tag - One selected tag.
 * @csspart tag-remove - The tag remove button.
 * @csspart panel - The floating panel.
 * @csspart search - The search input.
 * @csspart listbox - The `role="listbox"` scroller.
 * @csspart group - One `role="group"` wrapper around the options of an `<an-option-group>`.
 * @csspart option - One list item.
 * @csspart option-indicator - The selected check mark.
 * @csspart empty - The no-results row.
 * @csspart loading - The loading row.
 *
 * @cssproperty --an-select-height - Trigger height.
 * @cssproperty --an-select-bg - Trigger background.
 * @cssproperty --an-select-fg - Trigger foreground.
 * @cssproperty --an-select-border-color - Border colour.
 * @cssproperty --an-select-radius - Corner radius.
 * @cssproperty --an-select-font-size - Font size.
 * @cssproperty --an-select-padding-x - Horizontal padding.
 * @cssproperty --an-select-focus-ring - Focus ring colour.
 * @cssproperty --an-select-panel-bg - Panel background.
 * @cssproperty --an-select-panel-max-height - Listbox max height.
 * @cssproperty --an-select-min-width - Minimum control width.
 */
export class AnSelect extends AnElement {
  static override styles: string = selectStyles;

  static override formAssociated = true;

  static override defaults = {
    label: '',
    placeholder: '',
    size: 'md',
    name: '',
    disabled: false,
    required: false,
    invalid: false,
    multiple: false,
    searchable: false,
    loading: false,
    virtual: 'auto',
    maxTags: 3,
    loadMoreThreshold: 80,
  };

  /**
   * `value`, `values` and `open` are managed by hand: `value`/`values` seed the
   * selection without writing the attribute back, and `open` needs to drive the
   * popover instead of a plain re-render.
   */
  static override get observedAttributes(): string[] {
    return [
      ...super.observedAttributes,
      'value',
      'values',
      'open',
      'aria-label',
      'aria-labelledby',
    ];
  }

  declare label: string;
  declare placeholder: string;
  declare size: AnSelectSize;
  declare name: string;
  declare disabled: boolean;
  declare required: boolean;
  declare invalid: boolean;
  declare multiple: boolean;
  declare searchable: boolean;
  declare loading: boolean;
  declare virtual: AnSelectVirtual;
  declare maxTags: number;
  declare loadMoreThreshold: number;

  readonly #uid: string;
  readonly #triggerId: string;
  readonly #panelId: string;
  readonly #listboxId: string;
  readonly #labelId: string;

  /** Selected values; the single value lives at index 0. */
  #values: string[] = [];
  /** True once a value/values attribute or property supplied the selection. */
  #selectionSeeded = false;
  /** Reset target, captured on the first connected render. */
  #initialValues: string[] = [];
  #initialCaptured = false;

  #open = false;
  #query = '';
  #composing = false;
  #pendingMutationRender = false;

  #allOptions: OptionRecord[] = [];
  #visible: OptionRecord[] = [];
  #activeIndex = -1;
  #scrollTop = 0;
  /** `Date.now()` of the last `an-load-more` emission; throttles the event. */
  #lastLoadMore = 0;
  #pendingScrollTop: number | null = null;
  #pendingFocus: 'trigger' | 'search' | null = null;
  #pendingCaret: number | null = null;

  #searchTimer: ReturnType<typeof setTimeout> | null = null;
  #typeahead = '';
  #typeaheadTimer: ReturnType<typeof setTimeout> | null = null;

  #observer: MutationObserver | null = null;
  #popover: AnPopover | null = null;
  #formDisabled = false;
  #reflectingOpen = false;

  #nodeIds = new WeakMap<Element, string>();
  #nodeSeq = 0;

  #triggerEl: HTMLElement | null = null;
  #panelEl: HTMLElement | null = null;
  #listboxEl: HTMLElement | null = null;
  #searchEl: HTMLInputElement | null = null;
  #emptyEl: HTMLElement | null = null;
  #loadingEl: HTMLElement | null = null;

  constructor() {
    super();
    this.#uid = `an-select-${++selectUid}`;
    this.#triggerId = `${this.#uid}-trigger`;
    this.#panelId = `${this.#uid}-panel`;
    this.#listboxId = `${this.#uid}-listbox`;
    this.#labelId = `${this.#uid}-label`;

    this.addEventListener('click', this.#onClick);
    this.addEventListener('keydown', this.#onKeyDown);
    this.addEventListener('input', this.#onInput);
    this.addEventListener('compositionstart', this.#onCompositionStart);
    this.addEventListener('compositionend', this.#onCompositionEnd);
  }

  /** Current single value; `''` while nothing is selected. */
  get value(): string {
    return this.#values[0] ?? '';
  }

  /** Seeds the current value without reflecting it back onto the attribute. */
  set value(next: string) {
    this.#seed([String(next)]);
  }

  /** Current selection as a list; single-selects expose at most one entry. */
  get values(): string[] {
    return [...this.#values];
  }

  /** Seeds the selection from an array or a comma-separated string. */
  set values(next: string[] | string) {
    this.#seed(Array.isArray(next) ? next.map(String) : parseValuesAttribute(next));
  }

  /** Whether the panel is open. */
  get open(): boolean {
    return this.#open;
  }

  /** Opens or closes the panel programmatically. */
  set open(next: boolean) {
    this.#setOpen(Boolean(next));
  }

  /** Alias for `open`, matching the other overlay components. */
  get isOpen(): boolean {
    return this.#open;
  }

  /** A live snapshot of the light-DOM options. */
  get options(): AnSelectOption[] {
    return this.#readOptions().map(({ value, label, disabled }) => ({ value, label, disabled }));
  }

  /** Opens the panel. */
  show(): void {
    this.#setOpen(true);
  }

  /** Closes the panel. */
  close(): void {
    this.#setOpen(false);
  }

  /** Toggles the panel. */
  toggle(): void {
    this.#setOpen(!this.#open);
  }

  /** Selects every enabled option (single-selects pick the first one). */
  selectAll(): void {
    const pickable = this.#readOptions().filter(
      (option) => !option.disabled && option.value !== '',
    );
    const next = this.multiple
      ? pickable.map((option) => option.value)
      : pickable.slice(0, 1).map((option) => option.value);
    this.#commitProgrammatic(normalizeValues(next, this.multiple));
  }

  /** Clears the selection. */
  clear(): void {
    this.#commitProgrammatic([]);
  }

  /** Serializes the current selection the way `new FormData(form)` would. */
  override getFormData(): FormData | null {
    return super.getFormData();
  }

  /**
   * Constraint validation. Falls back to `internals.validity` on DOM shims that
   * expose `setValidity()` but not `checkValidity()`.
   */
  override checkValidity(): boolean {
    const internals = this.internals;
    if (internals === null) return true;
    if (typeof internals.checkValidity === 'function') return internals.checkValidity();
    return internals.validity?.valid ?? true;
  }

  /** Like `checkValidity()`, but emits `invalid` before reporting failure. */
  override reportValidity(): boolean {
    const internals = this.internals;
    if (internals !== null && typeof internals.reportValidity === 'function') {
      return internals.reportValidity();
    }
    if (this.checkValidity()) return true;
    this.dispatchEvent(new Event('invalid', { cancelable: true }));
    return false;
  }

  override attributeChangedCallback(
    name: string,
    oldValue: string | null,
    value: string | null,
  ): void {
    if (oldValue === value) return;

    if (name === 'value') {
      if (oldValue === value) return;
      this.#seed(value === null ? [] : [value]);
      return;
    }
    if (name === 'values') {
      if (oldValue === value) return;
      this.#seed(parseValuesAttribute(value));
      return;
    }
    if (name === 'open') {
      if (this.#reflectingOpen || oldValue === value) return;
      this.#setOpen(value !== null, { focus: false });
      return;
    }
    if (name === 'aria-label' || name === 'aria-labelledby') {
      if (oldValue !== value) this.requestUpdate();
      return;
    }
    if (name === 'multiple' && oldValue !== value) {
      this.#values = normalizeValues(this.#values, value !== null);
    }
    super.attributeChangedCallback(name, oldValue, value);
  }

  /** Re-renders while remembering focus, caret and scroll position. */
  override requestUpdate(): void {
    const root = this.shadowRoot;
    const active = root?.activeElement ?? null;
    const trigger = this.#triggerEl;
    const search = this.#searchEl;
    if (active !== null && search !== null && active === search) {
      this.#pendingFocus = 'search';
      this.#pendingCaret = search.selectionStart;
    } else if (active !== null && trigger !== null && trigger.contains(active)) {
      this.#pendingFocus = 'trigger';
      this.#pendingCaret = null;
    } else {
      this.#pendingFocus = null;
      this.#pendingCaret = null;
    }
    const list = this.#listboxEl;
    if (list !== null) {
      this.#scrollTop = list.scrollTop;
      this.#pendingScrollTop = list.scrollTop;
    }
    super.requestUpdate();
  }

  protected override onConnect(): void {
    this.#observer = new MutationObserver(this.#onMutations);
    this.#observer.observe(this, {
      childList: true,
      subtree: true,
      attributes: true,
      characterData: true,
    });
  }

  protected override onDisconnect(): void {
    this.#observer?.disconnect();
    this.#observer = null;
    this.#destroyPopover();
    this.#cancelSearchTimer();
    this.#cancelTypeahead();
  }

  protected override onFormReset(): void {
    this.#values = [...this.#initialValues];
    this.#selectionSeeded = true;
    this.#query = '';
    this.#activeIndex = -1;
    if (this.#searchEl !== null) this.#searchEl.value = '';
    this.#applyFilter();
    this.requestUpdate();
  }

  protected override onFormDisabled(disabled: boolean): void {
    this.#formDisabled = disabled;
    this.requestUpdate();
  }

  protected override formEntries(): Array<[string, string]> {
    if (this.#isDisabled() || this.name.length === 0 || this.#values.length === 0) return [];
    return this.#values.map((value) => [this.name, value] as [string, string]);
  }

  protected override render(): string {
    this.#refreshOptions();

    const disabled = this.#isDisabled();
    const label = this.label;
    const labelMarkup =
      label.length > 0
        ? `<label class="label" part="label" id="${this.#labelId}" for="${this.#triggerId}">` +
          `<span class="label-text">${escapeHtml(label)}</span></label>`
        : '';

    return (
      `<div class="base" part="base">` +
      `${labelMarkup}` +
      `<div class="control">` +
      `${this.#triggerMarkup(disabled)}` +
      `${this.#panelMarkup()}` +
      `</div>` +
      `</div>`
    );
  }

  protected override afterRender(): void {
    const root = this.shadowRoot;
    this.#triggerEl = (root?.querySelector('[part~="trigger"]') as HTMLElement | null) ?? null;
    this.#panelEl = (root?.querySelector('[part~="panel"]') as HTMLElement | null) ?? null;
    this.#listboxEl = (root?.querySelector('[part~="listbox"]') as HTMLElement | null) ?? null;
    this.#searchEl = (root?.querySelector('[part~="search"]') as HTMLInputElement | null) ?? null;
    this.#emptyEl = (root?.querySelector('[part~="empty"]') as HTMLElement | null) ?? null;
    this.#loadingEl = (root?.querySelector('[part~="loading"]') as HTMLElement | null) ?? null;

    if (
      !this.#initialCaptured &&
      (this.#selectionSeeded || this.#allOptions.length > 0)
    ) {
      this.#captureInitial();
    }

    if (this.#isDisabled() && this.#open) this.#setOpen(false, { focus: false });

    this.#applyPendingScroll();
    this.#bindListScroll();

    if (this.#open) {
      if (this.#activeIndex < 0 || this.#activeIndex >= this.#visible.length) this.#initActive();
      this.#paintList();
      this.#openPopover();
    } else {
      this.#destroyPopover();
    }

    this.#applyPendingFocus();
    this.#syncForm();
    this.#reflectHostState();
  }

  // ---------------------------------------------------------------------------
  // Rendering helpers
  // ---------------------------------------------------------------------------

  #triggerMarkup(disabled: boolean): string {
    const describedBy = this.getAttribute('aria-labelledby');
    const ariaLabel = this.getAttribute('aria-label');
    const labelledBy = this.label.length > 0 ? this.#labelId : describedBy;
    const accessibility =
      (labelledBy !== null ? ` aria-labelledby="${escapeHtml(labelledBy)}"` : '') +
      (labelledBy === null && ariaLabel !== null ? ` aria-label="${escapeHtml(ariaLabel)}"` : '') +
      (this.required ? ' aria-required="true"' : '') +
      (this.invalid ? ' aria-invalid="true"' : '') +
      (disabled ? ' aria-disabled="true"' : '');
    const active = this.#open ? this.#visible[this.#activeIndex] : undefined;
    const activeDescendant =
      active !== undefined ? ` aria-activedescendant="${active.id}"` : '';

    return (
      `<div class="trigger${this.#open ? ' is-open' : ''}" part="trigger"` +
      ` id="${this.#triggerId}"` +
      ` role="combobox"` +
      ` aria-haspopup="listbox"` +
      ` aria-expanded="${this.#open ? 'true' : 'false'}"` +
      ` aria-controls="${this.#listboxId}"` +
      `${activeDescendant}` +
      `${accessibility}` +
      ` tabindex="${disabled ? '-1' : '0'}">` +
      `${this.#triggerContent()}` +
      `<span class="chevron" aria-hidden="true"></span>` +
      `</div>`
    );
  }

  #triggerContent(): string {
    if (this.multiple) {
      const selected = this.#selectedViews();
      const limit = Math.max(0, Math.floor(this.maxTags));
      const shown = selected.slice(0, limit);
      const extra = selected.length - shown.length;
      const tags =
        shown
          .map(
            (view, index) =>
              `<span class="tag" part="tag">` +
              `<span class="tag-label">${escapeHtml(view.label)}</span>` +
              `<button type="button" class="tag-remove" part="tag-remove"` +
              ` data-tag-remove data-tag-index="${index}" tabindex="-1"` +
              ` aria-label="移除 ${escapeHtml(view.label)}">×</button>` +
              `</span>`,
          )
          .join('') + (extra > 0 ? `<span class="tag-overflow">+${extra}</span>` : '');
      return (
        `<span class="tags" part="tags"${selected.length === 0 ? ' hidden' : ''}>${tags}</span>` +
        this.#placeholderMarkup(selected.length > 0)
      );
    }

    const selected = this.#selectedViews()[0];
    const label = selected === undefined ? '' : selected.label;
    return (
      `<span class="value">${escapeHtml(label)}</span>` +
      this.#placeholderMarkup(selected !== undefined)
    );
  }

  #placeholderMarkup(hidden: boolean): string {
    return `<span class="placeholder" part="placeholder"${hidden ? ' hidden' : ''}>${escapeHtml(
      this.placeholder,
    )}</span>`;
  }

  #panelMarkup(): string {
    const visible = this.#visible;
    const loading = this.loading;
    const empty = visible.length === 0 && !loading;
    const searchMarkup = this.searchable
      ? `<div class="search-wrap">` +
        `<input class="search" part="search" type="search" placeholder="搜索…"` +
        ` aria-label="搜索" aria-controls="${this.#listboxId}"` +
        ` autocomplete="off" spellcheck="false" value="${escapeHtml(this.#query)}">` +
        `</div>`
      : '';

    return (
      `<div class="panel" part="panel" id="${this.#panelId}"${this.#open ? '' : ' hidden'}>` +
      `${searchMarkup}` +
      `<div class="listbox" part="listbox" id="${this.#listboxId}" role="listbox"` +
      `${this.multiple ? ' aria-multiselectable="true"' : ''}>` +
      `${this.#optionsMarkup()}` +
      `</div>` +
      `<div class="empty" part="empty"${empty ? '' : ' hidden'}>无匹配项</div>` +
      `<div class="loading" part="loading"${loading ? '' : ' hidden'}>` +
      `<span class="spinner" aria-hidden="true"></span>加载中…</div>` +
      `</div>`
    );
  }

  #optionsMarkup(): string {
    const total = this.#visible.length;
    if (total === 0) return '';
    const window = this.#virtualWindow();
    let rows = '';
    let openGroup: AnSelectGroup | null = null;
    for (let index = window.start; index < window.end; index += 1) {
      const option = this.#visible[index];
      if (option === undefined) continue;
      if (option.group !== openGroup) {
        if (openGroup !== null) rows += '</div>';
        openGroup = option.group;
        rows += this.#groupOpenMarkup(openGroup);
      }
      rows += this.#optionMarkup(index);
    }
    if (openGroup !== null) rows += '</div>';
    if (!this.#virtualEnabled()) return rows;
    // Keep the highlighted row in the DOM even when the user has scrolled the
    // viewport away from it, so `aria-activedescendant` still resolves.
    const activeOutside =
      this.#open &&
      this.#activeIndex >= 0 &&
      (this.#activeIndex < window.start || this.#activeIndex >= window.end);
    const activeRow = activeOutside
      ? `<div class="virtual-active" style="top:${this.#activeIndex * ITEM_HEIGHT}px">` +
        `${this.#optionMarkup(this.#activeIndex)}</div>`
      : '';
    return (
      `<div class="virtual-spacer" style="height:${total * ITEM_HEIGHT}px">` +
      `<div class="virtual-window" style="top:${window.start * ITEM_HEIGHT}px">` +
      `${rows}</div>${activeRow}</div>`
    );
  }

  /** Opens one `role="group"` wrapper; an empty group has no wrapper at all. */
  #groupOpenMarkup(group: AnSelectGroup | null): string {
    if (group === null) return '';
    const label =
      group.label.trim().length === 0
        ? ''
        : ` aria-label="${escapeHtml(group.label.trim())}"`;
    return (
      `<div class="group" part="group" role="group"${label}` +
      `${group.disabled ? ' data-disabled="true"' : ''}>`
    );
  }

  #optionMarkup(index: number): string {
    const option = this.#visible[index];
    if (option === undefined) return '';
    const selected = this.#values.includes(option.value);
    const active = index === this.#activeIndex;
    // Grouped options count inside their group; flat options count in the list.
    const setSize = option.group === null ? this.#visible.length : option.groupSize;
    const posInSet = option.group === null ? index + 1 : option.posInGroup;
    return (
      `<div class="option" part="option" id="${option.id}" role="option"` +
      ` data-option-index="${index}"` +
      ` aria-selected="${selected ? 'true' : 'false'}"` +
      `${option.disabled ? ' aria-disabled="true"' : ''}` +
      ` aria-posinset="${posInSet}" aria-setsize="${setSize}"` +
      `${active ? ' data-active="true"' : ''}>` +
      `<span class="option-content">${option.html}</span>` +
      `<span class="option-indicator" part="option-indicator" aria-hidden="true">✓</span>` +
      `</div>`
    );
  }

  // ---------------------------------------------------------------------------
  // Options
  // ---------------------------------------------------------------------------

  /**
   * Reads the light-DOM option source in document order.
   *
   * `<an-option-group>` wrappers are flattened into the list: every one of their
   * `<an-option>` children becomes a normal record that carries the group
   * metadata, so keyboard navigation, filtering and the virtual window keep
   * working on one flat index. A disabled group disables its options here, once,
   * instead of at every render.
   */
  #readOptions(): OptionRecord[] {
    const entries: Array<{ node: Element; group: AnSelectGroup | null }> = [];
    for (const child of Array.from(this.children)) {
      if (child.localName === 'an-option-group') {
        const group = readGroup(child);
        for (const nested of Array.from(child.children)) {
          entries.push({ node: nested, group });
        }
        continue;
      }
      entries.push({ node: child, group: null });
    }

    const groupSizes = new Map<AnSelectGroup, number>();
    for (const entry of entries) {
      if (entry.group === null || !isOptionNode(entry.node)) continue;
      groupSizes.set(entry.group, (groupSizes.get(entry.group) ?? 0) + 1);
    }

    const options: OptionRecord[] = [];
    const groupPositions = new Map<AnSelectGroup, number>();
    for (const entry of entries) {
      const { node, group } = entry;
      const position = group === null ? 0 : (groupPositions.get(group) ?? 0) + 1;
      if (group !== null) groupPositions.set(group, position);
      const size = group === null ? 0 : (groupSizes.get(group) ?? position);
      const record = this.#readOption(node, group, position, size);
      if (record !== null) options.push(record);
    }
    return options;
  }

  /** Builds the record for one light-DOM option node; `null` for anything else. */
  #readOption(
    node: Element,
    group: AnSelectGroup | null,
    posInGroup: number,
    groupSize: number,
  ): OptionRecord | null {
    if (node.localName === 'an-option') {
      const element = node as Element & Partial<AnOption>;
      const text = (node.textContent ?? '').trim();
      const value =
        typeof element.value === 'string' ? element.value : (node.getAttribute('value') ?? text);
      const label =
        typeof element.label === 'string' && element.label.trim() !== ''
          ? element.label
          : text || value;
      const ownDisabled = node.hasAttribute('disabled') || element.disabled === true;
      const inner = node.innerHTML.trim();
      return {
        node,
        value,
        label,
        text: text || value,
        disabled: ownDisabled || (group?.disabled ?? false),
        html: inner.length > 0 ? node.innerHTML : escapeHtml(text || label),
        id: this.#optionId(node),
        group,
        posInGroup,
        groupSize,
      };
    }
    if (node.localName === 'option') {
      const element = node as HTMLOptionElement;
      const text = (node.textContent ?? '').trim();
      const value = node.getAttribute('value') ?? text;
      const label = element.label || text || value;
      const ownDisabled = element.disabled === true || node.hasAttribute('disabled');
      return {
        node,
        value,
        label,
        text: text || value,
        disabled: ownDisabled || (group?.disabled ?? false),
        html: escapeHtml(text || label),
        id: this.#optionId(node),
        group,
        posInGroup,
        groupSize,
      };
    }
    return null;
  }

  #optionId(node: Element): string {
    let id = this.#nodeIds.get(node);
    if (id === undefined) {
      this.#nodeSeq += 1;
      id = `${this.#uid}-option-${this.#nodeSeq}`;
      this.#nodeIds.set(node, id);
    }
    return id;
  }

  #refreshOptions(): void {
    this.#allOptions = this.#readOptions();
    if (!this.#selectionSeeded && !this.#initialCaptured && this.#allOptions.length > 0) {
      const first = this.#allOptions.find((option) => !option.disabled && option.value !== '');
      this.#values =
        this.multiple || this.placeholder.length > 0 || first === undefined ? [] : [first.value];
      this.#selectionSeeded = true;
    }
    if (this.#initialCaptured) this.#pruneSelection();
    this.#applyFilter();
  }

  #pruneSelection(): void {
    const available = new Set(this.#allOptions.map((option) => option.value));
    const next = this.#values.filter((value) => available.has(value));
    if (!sameList(next, this.#values)) this.#values = next;
  }

  #applyFilter(): void {
    const query = this.#query.trim().toLowerCase();
    this.#visible =
      query.length === 0
        ? [...this.#allOptions]
        : this.#allOptions.filter((option) => this.#matches(option, query));
    if (this.#activeIndex >= this.#visible.length) this.#activeIndex = this.#visible.length - 1;
    this.#reindexGroups();
  }

  /**
   * Recomputes `aria-posinset` / `aria-setsize` for grouped options.
   *
   * A search can hide most of a group, so the group-relative position is only
   * valid for the current `#visible` list — the group title itself never takes
   * part in the filtering.
   */
  #reindexGroups(): void {
    const sizes = new Map<AnSelectGroup, number>();
    for (const option of this.#visible) {
      if (option.group === null) continue;
      sizes.set(option.group, (sizes.get(option.group) ?? 0) + 1);
    }
    const positions = new Map<AnSelectGroup, number>();
    for (const option of this.#visible) {
      if (option.group === null) continue;
      const position = (positions.get(option.group) ?? 0) + 1;
      positions.set(option.group, position);
      option.posInGroup = position;
      option.groupSize = sizes.get(option.group) ?? position;
    }
  }

  #matches(option: OptionRecord, query: string): boolean {
    return (
      option.label.toLowerCase().includes(query) ||
      option.text.toLowerCase().includes(query) ||
      option.value.toLowerCase().includes(query)
    );
  }

  #selectedViews(): AnSelectOption[] {
    return this.#values.map((value) => {
      const option = this.#allOptions.find((candidate) => candidate.value === value);
      return option === undefined
        ? { value, label: value, disabled: false }
        : { value: option.value, label: option.label, disabled: option.disabled };
    });
  }

  #captureInitial(): void {
    this.#initialValues = [...this.#values];
    this.#initialCaptured = true;
  }

  // ---------------------------------------------------------------------------
  // Open / close
  // ---------------------------------------------------------------------------

  #setOpen(next: boolean, options: { focus?: boolean; emit?: boolean } = {}): void {
    const focus = options.focus ?? true;
    const emit = options.emit ?? true;
    if (next && this.#isDisabled()) return;
    if (next === this.#open) {
      if (next && focus) this.#triggerEl?.focus();
      return;
    }

    this.#open = next;
    this.#reflectingOpen = true;
    this.toggleAttribute('open', next);
    this.#reflectingOpen = false;

    if (next) {
      this.#query = '';
      if (this.#searchEl !== null) this.#searchEl.value = '';
      this.#refreshOptions();
      this.#initActive();
      this.#panelEl?.removeAttribute('hidden');
      this.#triggerEl?.setAttribute('aria-expanded', 'true');
      this.#triggerEl?.classList.add('is-open');
      this.#paintList(true);
      this.#openPopover();
      if (focus) this.#triggerEl?.focus();
    } else {
      this.#destroyPopover();
      this.#cancelSearchTimer();
      this.#query = '';
      this.#activeIndex = -1;
      if (this.#searchEl !== null) this.#searchEl.value = '';
      this.#applyFilter();
      this.#panelEl?.setAttribute('hidden', '');
      this.#triggerEl?.setAttribute('aria-expanded', 'false');
      this.#triggerEl?.classList.remove('is-open');
      this.#triggerEl?.removeAttribute('aria-activedescendant');
      this.#paintList(true);
      if (focus) this.#triggerEl?.focus();
    }

    if (emit && this.isConnected) {
      this.emit(next ? 'an-select-open' : 'an-select-close');
    }
  }

  #openPopover(): void {
    this.#destroyPopover();
    if (!this.#open) return;
    const anchor = this.#triggerEl;
    const floating = this.#panelEl;
    if (anchor === null || floating === null) return;
    this.#popover = new AnPopover({
      anchor,
      floating,
      matchWidth: true,
      offset: 4,
      onClose: this.#onPopoverClose,
    });
    this.#popover.open();
  }

  #destroyPopover(): void {
    const popover = this.#popover;
    this.#popover = null;
    popover?.destroy();
  }

  #onPopoverClose = (): void => {
    if (!this.#open) return;
    this.#setOpen(false, { focus: false });
  };

  // ---------------------------------------------------------------------------
  // List painting and virtualization
  // ---------------------------------------------------------------------------

  #virtualEnabled(): boolean {
    const mode = oneOf(VIRTUAL_MODES, String(this.virtual), 'auto');
    if (mode === 'off') return false;
    if (mode === 'on') return true;
    return this.#visible.length > 200;
  }

  #virtualWindow(): { start: number; end: number } {
    const total = this.#visible.length;
    if (!this.#virtualEnabled()) return { start: 0, end: total };
    const viewport = this.#listboxEl?.clientHeight ?? 0;
    const height = viewport > 0 ? viewport : VIRTUAL_VIEWPORT;
    const first = Math.floor(this.#scrollTop / ITEM_HEIGHT);
    const perPage = Math.max(1, Math.ceil(height / ITEM_HEIGHT));
    const start = Math.max(0, first - VIRTUAL_BUFFER);
    let end = Math.min(total, first + perPage + VIRTUAL_BUFFER);
    if (end <= start) end = Math.min(total, start + 1);
    return { start, end };
  }

  #paintList(resetScroll = false): void {
    const list = this.#listboxEl;
    if (list === null) return;
    if (resetScroll) {
      this.#scrollTop = 0;
      list.scrollTop = 0;
    } else {
      this.#scrollTop = list.scrollTop;
    }
    list.innerHTML = this.#optionsMarkup();
    list.scrollTop = this.#scrollTop;
    this.#updateStatus();
    this.#syncActiveDescendant();
  }

  #updateStatus(): void {
    const loading = this.loading;
    if (this.#loadingEl !== null) this.#loadingEl.toggleAttribute('hidden', !loading);
    if (this.#emptyEl !== null) {
      this.#emptyEl.toggleAttribute('hidden', loading || this.#visible.length > 0);
    }
  }

  #syncActiveDescendant(): void {
    const trigger = this.#triggerEl;
    if (trigger === null) return;
    const active = this.#open ? this.#visible[this.#activeIndex] : undefined;
    if (active === undefined) trigger.removeAttribute('aria-activedescendant');
    else trigger.setAttribute('aria-activedescendant', active.id);
  }

  #bindListScroll(): void {
    const list = this.#listboxEl;
    if (list === null) return;
    list.addEventListener('scroll', this.#onScroll, { passive: true });
  }

  #onScroll = (): void => {
    const list = this.#listboxEl;
    if (list === null) return;
    const next = list.scrollTop;
    if (next === this.#scrollTop) return;
    this.#scrollTop = next;
    if (this.#virtualEnabled()) this.#paintList();
    this.#maybeLoadMore(list);
  };

  /**
   * Fires `an-load-more` once the listbox is within `load-more-threshold` of its
   * bottom. Throttled rather than debounced: a fast flick still produces one
   * event per 200ms instead of only one after the scrolling stops.
   *
   * No "has more" bookkeeping lives here — the consumer simply stops appending
   * options, so it must not fire the event twice in the same frame either.
   */
  #maybeLoadMore(list: HTMLElement): void {
    if (!this.#open) return;
    const scrollHeight = list.scrollHeight;
    if (scrollHeight <= 0 || scrollHeight <= list.clientHeight) return;
    const threshold = Math.max(0, this.loadMoreThreshold);
    const distance = scrollHeight - list.scrollTop - list.clientHeight;
    if (distance > threshold) return;
    const now = Date.now();
    if (now - this.#lastLoadMore < LOAD_MORE_INTERVAL) return;
    this.#lastLoadMore = now;
    this.emit<AnSelectLoadMoreDetail>('an-load-more', {
      scrollTop: list.scrollTop,
      scrollHeight,
      clientHeight: list.clientHeight,
    });
  }

  #initActive(): void {
    const selected = this.#values[0];
    let index =
      selected === undefined
        ? -1
        : this.#visible.findIndex((option) => option.value === selected && !option.disabled);
    if (index < 0) index = this.#firstEnabled();
    this.#activeIndex = index;
  }

  #firstEnabled(): number {
    return this.#visible.findIndex((option) => !option.disabled);
  }

  #setActive(index: number): void {
    this.#activeIndex = index;
    this.#scrollActiveIntoView();
    this.#paintList();
  }

  #moveActive(delta: number): void {
    const total = this.#visible.length;
    if (total === 0) return;
    const direction = delta >= 0 ? 1 : -1;
    let index = this.#activeIndex;
    let remaining = Math.abs(delta);
    let moved = false;
    while (remaining > 0) {
      const next = this.#nextEnabled(index, direction);
      if (next === index && moved) break;
      index = next;
      moved = true;
      remaining -= 1;
    }
    if (index >= 0) this.#setActive(index);
  }

  #nextEnabled(index: number, direction: number): number {
    const total = this.#visible.length;
    let cursor = index;
    for (let step = 0; step < total; step += 1) {
      if (cursor < 0) cursor = direction > 0 ? 0 : total - 1;
      else cursor = direction > 0 ? (cursor + 1) % total : (cursor - 1 + total) % total;
      if (!this.#visible[cursor].disabled) return cursor;
    }
    return index;
  }

  #scrollActiveIntoView(): void {
    const index = this.#activeIndex;
    const list = this.#listboxEl;
    if (index < 0 || list === null) return;
    const viewport = list.clientHeight > 0 ? list.clientHeight : VIRTUAL_VIEWPORT;
    const top = index * ITEM_HEIGHT;
    const bottom = top + ITEM_HEIGHT;
    let scrollTop = list.scrollTop;
    if (top < scrollTop) scrollTop = top;
    else if (bottom > scrollTop + viewport) scrollTop = bottom - viewport;
    list.scrollTop = scrollTop;
    this.#scrollTop = list.scrollTop;
  }

  #applyPendingScroll(): void {
    const top = this.#pendingScrollTop;
    this.#pendingScrollTop = null;
    if (top === null || this.#listboxEl === null) return;
    this.#listboxEl.scrollTop = top;
    this.#scrollTop = this.#listboxEl.scrollTop;
  }

  #applyPendingFocus(): void {
    const focus = this.#pendingFocus;
    const caret = this.#pendingCaret;
    this.#pendingFocus = null;
    this.#pendingCaret = null;
    if (focus === 'search' && this.#open && this.#searchEl !== null) {
      this.#searchEl.focus();
      const position = caret ?? this.#query.length;
      try {
        this.#searchEl.setSelectionRange(position, position);
      } catch {
        // Some DOM shims do not implement selection ranges on search inputs.
      }
    } else if (focus !== null && this.#triggerEl !== null) {
      this.#triggerEl.focus();
    }
  }

  // ---------------------------------------------------------------------------
  // Selection
  // ---------------------------------------------------------------------------

  #seed(input: Iterable<string>): void {
    this.#values = normalizeValues(input, this.multiple);
    this.#selectionSeeded = true;
    if (this.#open) this.#initActive();
    this.requestUpdate();
  }

  #commitProgrammatic(next: string[]): void {
    if (sameList(next, this.#values)) return;
    this.#values = [...next];
    this.#selectionSeeded = true;
    if (this.#open) this.#initActive();
    this.requestUpdate();
  }

  #selectOption(option: OptionRecord, originalEvent: Event | null): void {
    const before = this.#values;
    const next = this.multiple
      ? before.includes(option.value)
        ? before.filter((value) => value !== option.value)
        : [...before, option.value]
      : [option.value];
    const normalized = normalizeValues(next, this.multiple);
    const changed = !sameList(before, normalized);
    const searchFocused =
      this.#searchEl !== null && this.shadowRoot?.activeElement === this.#searchEl;

    this.#values = normalized;
    this.#selectionSeeded = true;

    if (!this.multiple) this.#setOpen(false, { focus: false });
    this.requestUpdate();
    if (!this.multiple || !searchFocused) this.#triggerEl?.focus();
    if (changed) this.#emitChange(originalEvent, option);
  }

  #removeTag(index: number, originalEvent: Event | null): void {
    const value = this.#values[index];
    if (value === undefined) return;
    const option = this.#allOptions.find((candidate) => candidate.value === value) ?? null;
    this.#values = this.#values.filter((_, position) => position !== index);
    this.#selectionSeeded = true;
    this.requestUpdate();
    this.#triggerEl?.focus();
    this.#emitChange(originalEvent, option);
  }

  #removeLastTag(originalEvent: Event): void {
    this.#removeTag(this.#values.length - 1, originalEvent);
  }

  #emitChange(originalEvent: Event | null, option: OptionRecord | AnSelectOption | null): void {
    this.emit('an-select-change', {
      value: this.value,
      values: [...this.#values],
      option:
        option === null
          ? null
          : { value: option.value, label: option.label, disabled: option.disabled },
      originalEvent,
    });
  }

  // ---------------------------------------------------------------------------
  // Form state
  // ---------------------------------------------------------------------------

  #syncForm(): void {
    const internals = this.internals;
    if (internals === null) return;

    if (this.#isDisabled()) {
      internals.setFormValue(null);
      internals.setValidity({});
      return;
    }

    if (this.#values.length === 0 || this.name.length === 0) {
      internals.setFormValue(null);
    } else if (this.multiple) {
      const data = new FormData();
      for (const value of this.#values) data.append(this.name, value);
      internals.setFormValue(data);
    } else {
      internals.setFormValue(this.#values[0]);
    }

    if (this.required && this.#values.length === 0) {
      internals.setValidity(
        { valueMissing: true },
        REQUIRED_MESSAGE,
        this.#triggerEl ?? undefined,
      );
    } else {
      internals.setValidity({});
    }
  }

  #reflectHostState(): void {
    const disabled = this.#isDisabled();
    if (this.required) this.setAttribute('aria-required', 'true');
    else this.removeAttribute('aria-required');
    if (this.invalid) this.setAttribute('aria-invalid', 'true');
    else this.removeAttribute('aria-invalid');
    if (disabled) this.setAttribute('aria-disabled', 'true');
    else this.removeAttribute('aria-disabled');
  }

  #isDisabled(): boolean {
    return Boolean(this.disabled) || this.#formDisabled;
  }

  // ---------------------------------------------------------------------------
  // Observers and search
  // ---------------------------------------------------------------------------

  #onMutations = (records: MutationRecord[]): void => {
    let relevant = false;
    for (const record of records) {
      if (record.type === 'attributes' && record.target === this) continue;
      relevant = true;
      break;
    }
    if (!relevant) return;
    if (this.#composing) {
      this.#pendingMutationRender = true;
      return;
    }
    this.requestUpdate();
  };

  #onInput = (event: Event): void => {
    const input = this.#searchEl;
    if (input === null || !event.composedPath().includes(input)) return;
    if (this.#composing) return;
    this.#query = input.value;
    this.#applyFilter();
    this.#activeIndex = this.#firstEnabled();
    this.#paintList(true);
    this.#scheduleSearch(input.value);
  };

  #onCompositionStart = (event: Event): void => {
    const input = this.#searchEl;
    if (input === null || !event.composedPath().includes(input)) return;
    this.#composing = true;
  };

  #onCompositionEnd = (event: Event): void => {
    const input = this.#searchEl;
    if (input === null || !event.composedPath().includes(input)) return;
    this.#composing = false;
    this.#query = input.value;
    this.#applyFilter();
    this.#activeIndex = this.#firstEnabled();
    this.#paintList(true);
    if (this.#pendingMutationRender) {
      this.#pendingMutationRender = false;
      this.requestUpdate();
    }
    this.#scheduleSearch(input.value);
  };

  #scheduleSearch(query: string): void {
    this.#cancelSearchTimer();
    this.#searchTimer = setTimeout(() => {
      this.#searchTimer = null;
      if (!this.isConnected) return;
      this.emit('an-search', { query });
    }, SEARCH_DEBOUNCE);
  }

  #cancelSearchTimer(): void {
    if (this.#searchTimer === null) return;
    clearTimeout(this.#searchTimer);
    this.#searchTimer = null;
  }

  #cancelTypeahead(): void {
    if (this.#typeaheadTimer === null) return;
    clearTimeout(this.#typeaheadTimer);
    this.#typeaheadTimer = null;
    this.#typeahead = '';
  }

  #handleTypeahead(key: string, event: KeyboardEvent): boolean {
    if (key.length !== 1 || event.ctrlKey || event.metaKey || event.altKey) return false;
    this.#typeahead += key.toLowerCase();
    if (this.#typeaheadTimer !== null) clearTimeout(this.#typeaheadTimer);
    this.#typeaheadTimer = setTimeout(() => {
      this.#typeaheadTimer = null;
      this.#typeahead = '';
    }, TYPEAHEAD_TIMEOUT);

    if (!this.#open) this.#setOpen(true);
    const query = this.#typeahead;
    const total = this.#visible.length;
    if (total === 0) return true;

    const start = query.length === 1 && this.#activeIndex >= 0 ? this.#activeIndex : -1;
    for (let offset = 0; offset < total; offset += 1) {
      const index = start < 0 ? offset : (start + offset + 1) % total;
      const option = this.#visible[index];
      if (option.disabled) continue;
      const haystack = `${option.label} ${option.text} ${option.value}`.toLowerCase();
      if (haystack.includes(query)) {
        this.#setActive(index);
        return true;
      }
    }
    return true;
  }

  // ---------------------------------------------------------------------------
  // Event handlers
  // ---------------------------------------------------------------------------

  #onClick = (event: MouseEvent): void => {
    if (this.#isDisabled()) return;
    const path = event.composedPath();

    for (const node of path) {
      if (!(node instanceof HTMLElement)) continue;
      if (!node.hasAttribute('data-tag-remove')) continue;
      const index = Number(node.dataset.tagIndex);
      if (!Number.isNaN(index)) this.#removeTag(index, event);
      return;
    }

    for (const node of path) {
      if (!(node instanceof HTMLElement)) continue;
      if (!node.hasAttribute('data-option-index')) continue;
      if (node.getAttribute('aria-disabled') === 'true') return;
      const index = Number(node.dataset.optionIndex);
      const option = this.#visible[index];
      if (option !== undefined) this.#selectOption(option, event);
      return;
    }

    if (this.#triggerEl !== null && path.includes(this.#triggerEl)) {
      this.#setOpen(!this.#open);
    }
  };

  #onKeyDown = (event: KeyboardEvent): void => {
    const path = event.composedPath();
    const trigger = this.#triggerEl;
    const search = this.#searchEl;
    const inSearch = search !== null && path.includes(search);
    const inTrigger = trigger !== null && path.includes(trigger);
    if (!inSearch && !inTrigger) return;

    const key = event.key;
    if (this.#isDisabled()) {
      if (key === 'Escape' && this.#open) this.#setOpen(false);
      return;
    }

    if (key === 'Escape') {
      if (this.#open) {
        this.#setOpen(false, { focus: true });
        this.#triggerEl?.focus();
        event.preventDefault();
      } else if (inSearch) {
        trigger?.focus();
      }
      return;
    }

    if (key === 'Tab') {
      if (this.#open) this.#setOpen(false, { focus: false });
      return;
    }

    if (inSearch) {
      // Home/End/Page keys edit the search text; only the list keys are ours.
      if (key === 'ArrowDown' || key === 'ArrowUp' || key === 'Enter') {
        event.preventDefault();
        if (!this.#open) this.#setOpen(true);
        else if (key === 'Enter') this.#activateActive(event);
        else this.#moveActive(key === 'ArrowDown' ? 1 : -1);
      }
      return;
    }

    switch (key) {
      case 'ArrowDown':
        event.preventDefault();
        if (this.#open) this.#moveActive(1);
        else this.#setOpen(true);
        return;
      case 'ArrowUp':
        event.preventDefault();
        if (this.#open) this.#moveActive(-1);
        else this.#setOpen(true);
        return;
      case 'Home':
        if (this.#open) {
          event.preventDefault();
          const first = this.#firstEnabled();
          if (first >= 0) this.#setActive(first);
        }
        return;
      case 'End':
        if (this.#open) {
          event.preventDefault();
          for (let index = this.#visible.length - 1; index >= 0; index -= 1) {
            if (!this.#visible[index].disabled) {
              this.#setActive(index);
              break;
            }
          }
        }
        return;
      case 'PageDown':
        if (this.#open) {
          event.preventDefault();
          this.#moveActive(10);
        }
        return;
      case 'PageUp':
        if (this.#open) {
          event.preventDefault();
          this.#moveActive(-10);
        }
        return;
      case 'Enter':
        event.preventDefault();
        if (this.#open) this.#activateActive(event);
        else this.#setOpen(true);
        return;
      case ' ':
        event.preventDefault();
        if (!this.#open) this.#setOpen(true);
        else this.#activateActive(event);
        return;
      case 'Backspace':
        if (this.multiple && this.#values.length > 0) {
          event.preventDefault();
          this.#removeLastTag(event);
        }
        return;
      default:
        if (this.#handleTypeahead(key, event)) event.preventDefault();
    }
  };

  #activateActive(originalEvent: Event): void {
    const option = this.#visible[this.#activeIndex];
    if (option === undefined || option.disabled) return;
    this.#selectOption(option, originalEvent);
  }
}

export { SIZES };
